CREATE TABLE products(id TEXT PRIMARY KEY,canonical_name TEXT NOT NULL,product_id TEXT UNIQUE,resolution_state TEXT NOT NULL CHECK(resolution_state IN('EXISTING_PRODUCT','NEW_PRODUCT','AMBIGUOUS_PRODUCT')),revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE product_variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),sku TEXT UNIQUE,color TEXT,dimensions TEXT,publication_state TEXT NOT NULL DEFAULT 'DRAFT',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE authoritative_sources(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('PRICE','INVENTORY')),name TEXT NOT NULL,version TEXT NOT NULL,location TEXT NOT NULL,effective_at TEXT,imported_at TEXT NOT NULL,checksum TEXT,status TEXT NOT NULL CHECK(status IN('ACTIVE','SUPERSEDED','INVALID')),is_authoritative INTEGER NOT NULL CHECK(is_authoritative IN(0,1)),operating_context TEXT NOT NULL,freshness_policy TEXT NOT NULL,UNIQUE(kind,operating_context,version));
CREATE UNIQUE INDEX one_active_source ON authoritative_sources(kind,operating_context) WHERE status='ACTIVE' AND is_authoritative=1;
CREATE TABLE source_references(id TEXT PRIMARY KEY,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,field TEXT NOT NULL,authoritative_source_id TEXT REFERENCES authoritative_sources(id),source_name TEXT NOT NULL,source_version TEXT,source_location TEXT,read_at TEXT NOT NULL,freshness_result TEXT,checksum TEXT,created_at TEXT NOT NULL);
CREATE TABLE prices(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(id),kind TEXT NOT NULL CHECK(kind IN('CONSUMER_PRICE','INTERNET_SALE_PRICE')),amount INTEGER NOT NULL,source_reference_id TEXT NOT NULL REFERENCES source_references(id),effective_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE inventory_snapshots(id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL,availability TEXT NOT NULL,source_reference_id TEXT NOT NULL REFERENCES source_references(id),read_at TEXT NOT NULL,freshness_result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE prompt_templates(id TEXT PRIMARY KEY,key TEXT UNIQUE NOT NULL,name TEXT NOT NULL,scope TEXT NOT NULL,content_type TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE prompt_versions(id TEXT PRIMARY KEY,prompt_template_id TEXT NOT NULL REFERENCES prompt_templates(id),version INTEGER NOT NULL,content TEXT NOT NULL,variables TEXT NOT NULL DEFAULT '[]',settings TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,UNIQUE(prompt_template_id,version));
CREATE TRIGGER prompt_versions_no_update BEFORE UPDATE ON prompt_versions BEGIN SELECT RAISE(ABORT,'PromptVersion is immutable');END;
CREATE TRIGGER prompt_versions_no_delete BEFORE DELETE ON prompt_versions BEGIN SELECT RAISE(ABORT,'PromptVersion is immutable');END;
CREATE TABLE jobs(id TEXT PRIMARY KEY,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,job_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE job_steps(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','READY','RUNNING','WAITING','BLOCKED','FAILED','SUCCEEDED','CANCELLED','SKIPPED')),reason_code TEXT,human_message TEXT,started_at TEXT,finished_at TEXT,created_at TEXT NOT NULL,CHECK(status NOT IN('WAITING','BLOCKED') OR (reason_code IS NOT NULL AND human_message IS NOT NULL)));
CREATE TABLE step_dependencies(job_step_id TEXT NOT NULL REFERENCES job_steps(id),depends_on_step_id TEXT NOT NULL REFERENCES job_steps(id),PRIMARY KEY(job_step_id,depends_on_step_id));
CREATE TABLE artifacts(id TEXT PRIMARY KEY,job_id TEXT REFERENCES jobs(id),artifact_type TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('GENERATED','VALIDATING','VALIDATED','INVALID')),content TEXT,created_at TEXT NOT NULL);
CREATE TABLE generation_runs(id TEXT PRIMARY KEY,job_step_id TEXT REFERENCES job_steps(id),prompt_version_id TEXT REFERENCES prompt_versions(id),artifact_id TEXT REFERENCES artifacts(id),gateway TEXT,mode TEXT,started_at TEXT,finished_at TEXT);
CREATE TABLE publication_runs(id TEXT PRIMARY KEY,job_id TEXT REFERENCES jobs(id),adapter TEXT NOT NULL,result TEXT,created_at TEXT NOT NULL);
CREATE TABLE verification_runs(id TEXT PRIMARY KEY,publication_run_id TEXT REFERENCES publication_runs(id),status TEXT,result TEXT,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,timestamp TEXT NOT NULL,evidence_reference TEXT,metadata TEXT NOT NULL DEFAULT '{}');
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'AuditEvent is append-only');END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'AuditEvent is append-only');END;
CREATE TABLE execution_reports(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),status TEXT NOT NULL,report TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE final_product_approvals(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),approver TEXT NOT NULL,approved_at TEXT NOT NULL,product_revision INTEGER NOT NULL,source_versions TEXT NOT NULL,prompt_versions TEXT NOT NULL,artifact_ids TEXT NOT NULL,qa_evidence TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE qa_results(id TEXT PRIMARY KEY,gate TEXT NOT NULL CHECK(gate IN('DATA','CONTENT','MEDIA','PUBLICATION')),check_key TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('PASS','FAIL')),reason TEXT,evidence TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
